}

func (s *Staging) verify() error {
	info, err := os.Lstat(s.Dir)
	if err != nil {
		return err
	}
	if !info.IsDir() || !os.SameFile(info, s.info) {
		return fmt.Errorf("refusing staging dir %q: no longer the directory this install created", s.Dir)
	}
